def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    my_score = 0
    opp_score = 0

    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    start12 = n - 12
    if start12 < 0:
        start12 = 0

    opp_d12 = 0
    my_d12 = 0
    for i in range(start12, n):
        if history[i][1] == 'D':
            opp_d12 += 1
        if history[i][0] == 'D':
            my_d12 += 1

    opp_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    remaining = 100 - n
    if remaining == 0:
        return 'D'

    if opp_d >= max(6, int(n * 0.6) + 2) or opp_d12 >= 8 or opp_streak >= 5:
        return 'D'

    if opp_streak >= 3 and opp_d >= 3 and opp_d > my_d:
        return 'D'

    if n <= 6 and opp_d >= 3 and my_d <= 1:
        return 'D'

    if opp_d == 0 and n >= 90:
        confirmed = False
        for i in range(n - 1):
            if history[i][0] == 'D' and history[i + 1][0] == 'C' and history[i][1] == 'C' and history[i + 1][1] == 'C':
                confirmed = True
                break

        if opp_last == 'C':
            if my_last == 'D':
                return 'D' if confirmed else 'C'
            return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_streak <= 2 or my_d >= opp_d or my_score >= opp_score:
                return 'C'
            if rng.random() < 0.6:
                return 'C'
            return 'D'

        if my_d == 0 and opp_d >= 2:
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if opp_streak <= 2 and opp_d <= max(2, n // 4):
                return 'C'
            if my_score >= opp_score and rng.random() < 0.65:
                return 'C'
            return 'D'

        if opp_d <= 1:
            if opp_d12 >= 3 and opp_d > n // 5:
                return 'D'
            return 'C'

        if opp_streak >= 2 or opp_d12 >= 4:
            return 'D'

        if opp_d <= max(2, n // 5) and my_score >= opp_score + 3:
            if rng.random() < 0.4:
                return 'C'

        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if my_last == 'D':
        if opp_d == 0:
            return 'C'

        if opp_d <= 2 and opp_d12 <= 1 and my_d12 <= 3 and my_score >= opp_score and rng.random() < 0.25:
            return 'D'

        return 'C'

    if remaining <= 5 and opp_d <= 1 and rng.random() < 0.3:
        return 'D'

    return 'C'
